function persist(){if(window.FILTRIP_PRESENTING)return;try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{}}

// Preserve the old snapshot while migrating the replaced place-selection category.
if (state.favorites.some(id => id.startsWith('travel-')) || state.favoriteCategory === 'travel') {
 try { if (!localStorage.getItem('filtrip-before-video-category')) localStorage.setItem('filtrip-before-video-category',JSON.stringify(state)); } catch {}
 state.favorites = state.favorites.filter(id => !id.startsWith('travel-'));
 if (state.favoriteCategory === 'travel') { state.favoriteCategory='video';state.favoriteGenre=null; }
 for (const view of [...state.history,state.guideCheckpoint].filter(Boolean)) if(view.favoriteCategory==='travel'){view.favoriteCategory='video';view.favoriteGenre=null;}
}
const minaWorld = () => ({id:'mina',name:'ミナ',members:1,entry:'小説',tags:['20代','大学生','美術','小説','お絵かき'],kind:'person'});
const minaLikes = ['history','craft','soda','lamp','night','tools'];
const viewFields=['screen','favoriteCategory','favoriteGenre','favoriteQuery','favoriteMode','quizPage','tab','detail','detailOrigin','detailSection','world','editing','profileId','chatId','listKind','homeMode','homeTab','homeQuery','homeLimit','worldLimit','personQuery','workQuery','searchCategory','searchCategories','searchFilters','searchResultIds','peopleLimit','searchDetailsOpen'];
function snapshot(){const view={};for(const key of viewFields)view[key]=structuredClone(state[key]);view.scroll=$('.app-scroll')?.scrollTop||0;return view;}
function restore(view){for(const key of viewFields)if(key in view)state[key]=structuredClone(view[key]);ensureSearchChoices();if(state.screen==='about')state.profileDraft={...state.profile};if(state.screen==='sources')state.sourceDraft=[...state.sources];if(state.screen==='favorites'&&state.favoriteMode==='edit')state.favoriteDraft=[...state.favorites];render();if($('.app-scroll'))$('.app-scroll').scrollTop=view.scroll||0;persist();}
function checkpoint(){state.guideCheckpoint=snapshot();}
function sameGuideView(){const cp=state.guideCheckpoint;return cp?.screen===state.screen&&cp.world?.id===state.world.id&&cp.favoriteMode===state.favoriteMode&&cp.editing===state.editing&&(!['why','article','video','post','music','added'].includes(state.screen)||cp.detail===state.detail);}
function go(target,{guided=false,detail,origin,direction='forward'}={}){window.FILTRIP_MOTION?.prepare(direction);const old=snapshot();state.history.push(old);if(state.history.length>60)state.history.shift();state.screen=target;if(target==='about')state.profileDraft={...state.profile};if(target==='sources')state.sourceDraft=[...state.sources];if(detail)state.detail=detail;if(origin)state.detailOrigin=structuredClone(origin);render();if(guided){checkpoint();persist();}}
function back(){window.FILTRIP_MOTION?.prepare('back');if(state.screen==='quiz'&&state.quizPage>0){state.quizPage--;render();return;}const favoritePosition=state.screen==='favorites'&&state.favoriteMode==='onboarding'?{favoriteCategory:state.favoriteCategory,favoriteGenre:state.favoriteGenre,favoriteQuery:state.favoriteQuery}:null;const old=state.history.pop();if(old){restore(old);if(favoritePosition&&old.screen==='about'){Object.assign(state,favoritePosition);persist();}}else go('home',{direction:'back'});}

function homeWorld(){return {id:'home-recommend',name:'ホームのおすすめ',members:people.length,entry:'あなたの好き',kind:'group',tags:[],personIds:people.map(p=>p.id),contentIds:[...catalog,...relatedVideos].map(c=>c.id)};}
function currentWorld(id){if(state.screen==='home')return state.homeMode==='my'&&state.origins[id]?state.origins[id].world:homeWorld();return state.screen==='profile'?personWorld(state.profileId):state.world;}
function openContent(id){state.detailSection=['home','mine'].includes(state.screen)?state.screen:['why','article','video','post','music'].includes(state.screen)?state.detailSection||'search':'search';const c=contentById(id);const origin=state.screen==='mine'&&state.origins[id]?state.origins[id].world:['why','article','video','post','music'].includes(state.screen)?state.detailOrigin:currentWorld(id);go(c.type==='動画'?'video':c.type==='投稿'?'post':c.type==='音楽'?'music':'article',{detail:id,origin,guided:state.screen==='world'&&state.world.id==='readers'&&c.id==='lamp'});}
function worldCount(c,world=state.world){if(world.personIds)return world.personIds.filter(id=>(personLikes.get(id)||[]).includes(c.id)).length;return world.kind==='person'?1:Math.min(world.members,Math.max(0,Math.round(c.n*world.members/84)));}
function add(id){if(state.added.includes(id)){removeSaved(id);return;}const c=contentById(id);const world=['world','home','profile'].includes(state.screen)?currentWorld(id):state.detailOrigin;state.added.push(id);state.origins[id]={world:structuredClone(world),date:new Date().toISOString()};state.detail=id;state.detailOrigin=structuredClone(world);go('added',{guided:id==='lamp'&&world.id==='readers'});}

let removedSave=null,removeNoticeTimer;
function removeSaved(id){const index=state.added.indexOf(id);if(index<0)return;removedSave={id,index,origin:state.origins[id]};state.added.splice(index,1);delete state.origins[id];render(true);clearTimeout(removeNoticeTimer);removeNoticeTimer=setTimeout(()=>{removedSave=null;document.querySelector('.save-notice')?.remove();},6000);}
function undoSaved(){if(!removedSave)return;const saved=removedSave;if(!state.added.includes(saved.id))state.added.splice(Math.min(saved.index,state.added.length),0,saved.id);if(saved.origin)state.origins[saved.id]=saved.origin;removedSave=null;clearTimeout(removeNoticeTimer);render(true);}
function saveNotice(){return removedSave?'<div class="save-notice" role="status"><span>保存を解除しました</span><button data-action="undo-save">元に戻す</button></div>':'';}
function relatedContents(c){const world=state.detailOrigin,source=[...catalog,...relatedVideos];return source.sort((a,b)=>c.id==='repair'?Number(b.id.startsWith('repair-'))-Number(a.id.startsWith('repair-')):0).filter(x=>x.id!==c.id&&x.type===c.type&&(world.contentIds?world.contentIds.includes(x.id):worldCount(x,world)>0)).slice(0,3);}
function relatedSection(c){const list=relatedContents(c);return list.length?`<div class="section-heading"><h3>この世界の人が好きな${c.type}</h3></div>${list.map(x=>contentCard(x)).join('')}`:'';}
function nav(active=''){return `<nav class="app-nav" aria-label="アプリ内ナビゲーション">${[['home','home','ホーム'],['search','search','探す'],['mine','book','マイワールド'],['messages','message','メッセージ']].map(([s,i,l])=>`<button data-go="${s}" class="${active===s?'active':''}" ${active===s?'aria-current="page"':''}>${functionalIcon(i)}<span>${l}</span></button>`).join('')}</nav>`;}
function header(title,backButton=true,right=''){return `<header class="app-header">${backButton?'<button class="back" data-action="back" aria-label="前の画面に戻る">←</button>':'<span class="header-end"></span>'}<h1 class="${title==='FILTRIP'?'wordmark':''}" tabindex="-1">${title}</h1><span class="header-end">${right}</span></header>`;}
function shell(title,body,{foot='',active='',noNav=false,backButton=true,right='',className=''}={}){return header(title,backButton,right)+`<section class="app-scroll ${className}" tabindex="0" aria-label="${title}の内容">${body}</section>`+(foot?`<div class="action-foot">${foot}</div>`:'')+(noNav?'':nav(active));}
const primary=(label,action,disabled=false)=>`<button class="primary" data-action="${action}" ${disabled?'disabled':''}>${label}<span aria-hidden="true">›</span></button>`;
const thumb=c=>`<div class="thumb ${escapeHTML(c.id)}" aria-hidden="true">${window.FILTRIP_CURATED_MEDIA?.(c,'content-art')||((c.art||baseCatalog.some(b=>b.id===c.id))?icon(c.art||c.id,'content-art'):(window.FILTRIP_MEDIA?.(c,'content-art')||icon(c.icon||'book','content-art')))}${c.type==='動画'?'<span class="thumb-play">▶</span>':''}</div>`;
function contentCard(c,action='detail'){const inert=action==='noop',tag=inert?'div':'button';return `<${tag} class="content-card ${c.curated?'curated-card':''} ${c.original&&c.type==='記事'?'original-article':''}" data-content-type="${c.type}" ${inert?'':`data-action="${action}" data-id="${c.id}"`}>${thumb(c)}<span class="card-copy"><small>${c.type} · ${escapeHTML(c.providerCreator?.name||c.by)}</small><strong>${escapeHTML(c.title)}</strong><p>${escapeHTML(c.desc)}</p>${sourceBadge(c)}</span></${tag}>`;}

function choice(label,group,selected){return `<button class="choice ${selected?'selected':''}" data-select="${group}" data-value="${escapeHTML(label)}" aria-pressed="${selected}">${escapeHTML(label)}</button>`;}
function addButton(c,small=false){return `<button class="${small?'add-small':'primary'}" data-action="add" data-id="${c.id}" aria-label="${escapeHTML(c.title)}${state.added.includes(c.id)?'の保存を解除':'をMY WORLDに追加'}">${small?`<span>${state.added.includes(c.id)?'✓':icon('addCircle')}</span>`:state.added.includes(c.id)?'✓ ': '＋ '}${state.added.includes(c.id)?'保存済み':'MY WORLD'}</button>`;}
function worldItem(c){return `<article class="world-item-v4" data-content-id="${c.id}">${c.type==='投稿'?postPreview(c):contentCard(c)}<div class="world-card-footer"><button class="likers-link" data-action="content-likers" data-id="${c.id}">${functionalIcon('people')} ${state.world.members}人中 <b>${worldCount(c)}人</b>が好き</button>${addButton(c,true)}</div></article>`;}

function favoriteIds(){return state.screen==='favorites'&&state.favoriteMode==='edit'?(state.favoriteDraft||state.favorites):state.favorites;}
function selectedWorks(){return favoriteIds().map(workById).filter(Boolean);}
function favoriteFoot(){return `${state.favoriteCategory?`<nav class="favorite-switcher" aria-label="別のカテゴリを選ぶ">${categories.map(c=>`<button data-category="${c.id}" aria-pressed="${state.favoriteCategory===c.id}">${c.name}</button>`).join('')}</nav>`:''}<div class="count-action"><button class="favorite-count" data-action="show-selection" aria-expanded="false">${favoriteIds().length}件選択中</button>${primary(state.favoriteMode==='onboarding'?'次へ':'選択を保存',state.favoriteMode==='onboarding'?'favorites-next':'favorites-save',state.favoriteMode==='onboarding'&&!favoriteIds().length)}</div>`;}
function workCard(w){return `<button class="work-card ${favoriteIds().includes(w.id)?'selected':''}" data-work="${w.id}" aria-pressed="${favoriteIds().includes(w.id)}">${categoryIcon(w.icon,'work-art')}<span><strong>${escapeHTML(w.title)}</strong><small>${w.categoryName} · ${w.genre}</small></span><span class="heart" aria-hidden="true">${favoriteIds().includes(w.id)?'♥':'♡'}</span></button>`;}
function favoriteResults(){const cat=categories.find(c=>c.id===state.favoriteCategory);if(state.favoriteQuery.trim()){const q=state.favoriteQuery.toLocaleLowerCase();const matches=works.filter(w=>`${w.title} ${w.genre} ${w.categoryName}`.toLocaleLowerCase().includes(q));return `<p class="search-result-count">${matches.length}件見つかりました</p><div class="work-list">${matches.length?matches.map(workCard).join(''):'<p class="empty">見つかりませんでした。作品名やジャンルを変えて探してみてください。</p>'}</div>`;}if(!cat)return `<div class="favorites-grid favorite-categories">${categories.map(c=>`<button class="favorite" data-category="${c.id}">${categoryIcon(c.icon)}<strong>${c.name}</strong><small>${Object.keys(c.genres).slice(0,2).join('・')} など</small><span class="category-count">${selectedWorks().filter(w=>w.category===c.id).length||'›'}</span></button>`).join('')}</div>`;if(!state.favoriteGenre)return `<h2>${cat.name}</h2><p class="sub">知っている作品や好きな人から選んでみましょう。</p><details class="favorite-genre-filter"><summary>ジャンルで絞る</summary><div class="genre-grid">${Object.entries(cat.genres).map(([genre,names])=>`<button class="genre-card" data-genre="${genre}"><strong>${genre}</strong><small>${names.length}件</small><span>›</span></button>`).join('')}</div></details><div class="popular-work-list work-list">${works.filter(w=>w.category===cat.id&&(window.FILTRIP_FAVORITE_LIBRARY?.[cat.id]?.[w.genre]||[]).includes(w.title)).map(workCard).join('')}</div>`;return `<h2>${state.favoriteGenre}</h2><p class="sub">${cat.id==='video'&&state.favoriteGenre==='ゲーム実況'?'好きなチャンネル・クリエイターを選んでください。':'好きなものを選んでください。'}</p><div class="work-list">${works.filter(w=>w.category===cat.id&&w.genre===state.favoriteGenre).map(workCard).join('')}</div><button class="secondary" data-action="favorite-other">${cat.name}のほかのジャンルを選ぶ</button>`;}
function quizScore(axis){const values=questions.map((q,i)=>q[2]===axis?state.answers[i]:null).filter(v=>v!==null);return values.reduce((sum,n)=>sum+n,0)/(values.length||1);}
function resultDetails(){const social=quizScore('social'),curiosity=quizScore('curiosity'),planning=quizScore('planning');return {title:social>1.3?'みんなと発見する好奇心派':curiosity>1.3?'好きなものを深める探究派':planning>1.3?'じっくり旅する探究派':'マイペースな好奇心派',lines:[social<.7?'一人の時間を大切にする':social>1.3?'人との時間から元気をもらう':'心地よい距離感を大切にする',curiosity<.7?'新しいことに前向き':curiosity>1.3?'好きなものを深く味わう':'気になったことを確かめたい',planning<.7?'予定は柔軟に決めたい':planning>1.3?'見通しを持って楽しみたい':'余白を残して過ごしたい'],bars:[Math.round((2-social)/2*70+20),Math.round((2-curiosity)/2*70+20),Math.round((2-planning)/2*70+20)]};}
function conversationMessage(text,time,mine){return `<div class="message-row ${mine?'mine':'received'}">${mine?'':`<div class="message-avatar" aria-label="ミナ">${icon('mina')}</div>`}<div class="message ${mine?'mine':''}" aria-label="${mine?'あなた':'ミナ'}のメッセージ">${escapeHTML(text)}<time>${time}</time></div></div>`;}
function legacyScreen(){
  const c=contentById(state.detail);
  switch(state.screen){
  case 'welcome':return `<section class="app-scroll welcome"><div class="welcome-logo">FILTRIP</div><small>FILTER × TRIP</small><div class="welcome-art">${icon('welcome')}</div><h2>誰かの「好き」を通して、<br>まだ知らない世界へ。</h2><p class="english">Take a trip through someone else's filter.</p>${primary('旅をはじめる','start')}<button class="text-button" data-action="skip-onboarding">まずは世界を見てみる</button></section>`;
  case 'about':return shell('あなたについて',`<div class="progress-line"><span style="width:33%"></span></div><h2>あなたについて教えてください</h2><h3>年代</h3><div class="choices">${['10代','20代','30代','40代以上'].map(x=>choice(x,'age',state.age===x)).join('')}</div><h3>過ごし方</h3><div class="choices habits-choices">${['夜型','朝型','一人時間が好き','人と話すのが好き'].map(x=>choice(x,'habits',state.habits.includes(x))).join('')}</div><h3>関心</h3><div class="choice-grid">${[['デザイン','art'],['ゲーム','game'],['音楽','headphone'],['建築','building'],['読書','book'],['旅行','mountain']].map(([x,i])=>`<button class="choice ${state.interests.includes(x)?'selected':''}" data-select="interests" data-value="${x}" aria-pressed="${state.interests.includes(x)}">${icon((i==='art'||i==='headphone')&&!state.interests.includes(x)?i:({art:'aboutArt',game:'aboutGame',headphone:'aboutHeadphone',building:'aboutBuilding',book:'aboutBook',mountain:'aboutMountain'}[i]||i))}<span>${x}</span></button>`).join('')}</div>`,{noNav:true,right:state.editing==='about'?'':'1 / 3',foot:primary(state.editing==='about'?'変更を保存':'次へ',state.editing==='about'?'about-save':'about-next',!state.age)});
  case 'favorites':{const cat=categories.find(x=>x.id===state.favoriteCategory);return shell('好きなものを選ぼう',`${state.favoriteMode==='onboarding'?'<div class="progress-line"><span style="width:66%"></span></div>':''}<label class="favorite-search"><span class="sr-only">作品・作者・ジャンルを検索</span>${functionalIcon('search')}<input id="favorite-search" class="search-input" placeholder="作品・作者・ジャンルを検索" value="${escapeHTML(state.favoriteQuery)}" autocomplete="off"><button data-action="clear-favorite-search" aria-label="検索をクリア" ${state.favoriteQuery?'':'hidden'}>×</button></label><nav class="favorite-breadcrumb" aria-label="好きなものの階層"><button data-action="favorite-root">すべて</button>${cat?`<span>›</span><button data-category="${cat.id}">${cat.name}</button>`:''}${state.favoriteGenre?`<span>›</span><span>${state.favoriteGenre}</span>`:''}</nav><div id="favorite-results">${favoriteResults()}</div><div id="favorite-selection" class="favorite-selection" hidden></div>`,{noNav:true,right:state.favoriteMode==='onboarding'?'2 / 3':'',foot:favoriteFoot()});}
  case 'quiz':{const start=state.quizPage*3;const answered=state.answers.filter(x=>x!==null).length;return shell('性格診断',`<div class="progress-line"><span style="width:${answered/12*100}%"></span></div><div class="quiz-pagination"><span>${state.quizPage+1} / 4 ページ</span><span>${answered} / 12 回答</span></div><h2>あなたの楽しみ方を知ろう</h2><p class="sub">今の自分に近いものを選んでください。</p>${questions.slice(start,start+3).map(([q,opts],n)=>{const idx=start+n;return `<fieldset class="quiz-box"><legend>Q${idx+1}　${q}</legend>${opts.map((o,k)=>`<label class="quiz-option"><input type="radio" name="q${idx}" value="${k}" data-quiz="${idx}" ${state.answers[idx]===k?'checked':''}><span>${o}</span></label>`).join('')}</fieldset>`;}).join('')}<button class="text-button" data-action="quiz-skip">診断はあとで</button>`,{noNav:true,right:state.editing==='quiz'?'':'3 / 3',foot:`<div class="quiz-footer"><button class="quiz-skip-visible" data-action="quiz-skip">あとで</button>${state.quizPage?'<button class="secondary" data-action="quiz-prev">前の3問</button>':''}${primary(state.quizPage===3?'結果を見る':'次の3問','quiz-next',state.answers.slice(start,start+3).includes(null))}</div>`});}
  case 'result':{const result=resultDetails();return shell('診断結果',`<h2>あなたの性格傾向</h2><div class="result-art">${icon('result')}</div><h2 class="result-title">${result.title}</h2><p class="result-description">${result.lines[0]}。<br>自分らしいペースで世界を広げるタイプ。</p><div class="box"><h3>あなたの傾向</h3>${result.lines.map((x,i)=>`<div class="bar-row">${icon(['book','leaf','calendar'][i])}<div><span>${x}</span><div class="bar"><span style="width:${result.bars[i]}%"></span></div></div></div>`).join('')}</div>`,{noNav:true,foot:primary(state.editing==='quiz'?'結果を保存':'自分の世界へ','result-next')});}
  case 'sources':return shell('コンテンツの表示',`<p class="sub">ホームの「すべて」に表示する種類を選べます。種類別のタブでは、選択に関係なく閲覧できます。</p>${[['動画','video','動画・チャンネル'],['音楽','music','曲・アルバム・プレイリスト'],['記事','book','ニュース・ブログ・Web記事'],['投稿','message','公開された投稿']].map(([x,i,sub])=>`<div class="source">${icon(i)}<div><strong>${x==='記事'?'記事・Web':x==='投稿'?'SNS・投稿':x}</strong><small>${sub}</small></div><button role="switch" aria-label="${x}を表示" aria-checked="${(state.sourceDraft||state.sources).includes(x)}" data-select="sources" data-value="${x}"></button></div>`).join('')}<p class="bottom-note">コンテンツの種類は、あとから変更できます。</p>`,{noNav:false,active:'mine',foot:primary('保存する','sources-save',!(state.sourceDraft||state.sources).length)});
  case 'home':return shell('あなたの世界',`<button class="discovery" data-action="home-search">${icon('leaf')}<span>今日の発見 <b>3件</b></span><span>›</span></button>${['soda','history','craft'].map(contentById).filter(x=>state.sources.includes(x.type)).map(c=>`<article class="home-content">${contentCard({...c,art:{soda:'homeSoda',history:'homeHistory',craft:'homeCraft'}[c.id]})}<div class="world-summary">${functionalIcon('people')} 好みが近い${c.n+11}人が好き</div></article>`).join('')||'<p class="empty">今日は「投稿」に新しい発見があります。</p>'+contentCard(contentById('post'))}`,{backButton:false,active:'home',right:'<button data-action="settings" aria-label="設定">⚙</button>',foot:primary('誰かの世界を探す','home-search')});
  case 'search':return shell('誰の世界を見たい？',`<h3>入口にする好きなもの</h3><label class="search-entry"><span class="sr-only">入口にする作品・ジャンル</span><input id="entry-input" class="search-input" placeholder="作品・ジャンルを入力" value="${escapeHTML(state.filters.favorite)}" maxlength="60"></label><div class="choices">${['小説','音楽','ゲーム'].map(x=>choice(x,'filter-favorite',state.filters.favorite===x)).join('')}</div>${selectedWorks().length?`<div class="selected-entries">${selectedWorks().slice(0,4).map(w=>`<button class="chip" data-select="filter-favorite" data-value="${escapeHTML(w.title)}">${escapeHTML(w.title)}</button>`).join('')}</div>`:''}<h3>人の特徴</h3><div class="search-conditions">${[['年代','age',['20代','10代','30代','指定なし']],['性別','gender',['女性','男性','指定なし']],['所属','job',['大学生','社会人','指定なし']],['関心','interest',['美術','音楽','カフェ','指定なし']],['趣味','hobby',['お絵かき','音楽','ゲーム','指定なし']]].map(([label,k,opts])=>`<div class="condition-row"><h3>${label}</h3><div class="choices">${opts.map(x=>choice(x,'filter-'+k,state.filters[k]===x)).join('')}</div></div>`).join('')}</div><p class="result-count">この条件に近い <strong>84人</strong></p>`,{active:'search',foot:primary('FIND THE WORLD','search-run',!state.filters.favorite.trim())});
  case 'results':return shell('WORLDS',`<div class="chips">${Object.values(state.filters).filter(x=>x!=='指定なし').map(x=>`<span class="chip">${escapeHTML(x)}</span>`).join('')}</div><p class="results-intro"><strong>84</strong>人の世界が見つかりました</p><div class="result-sort"><button data-action="sort-worlds">${state.sort} ⇅</button></div>${resultWorldCards()}`,{active:'search'});
  case 'world':{const items=state.world.kind==='person'?minaLikes.map(contentById):state.world.id==='artists'?[...catalog].sort((a,b)=>Number(['craft','tools','history'].includes(b.id))-Number(['craft','tools','history'].includes(a.id))):catalog;return shell('FILTRIP',`<div class="trip-banner"><span><small>NOW TRIPPING</small>他者の世界を閲覧中</span><button data-go="mine">自分に戻る ›</button></div><h2 class="world-title">${state.world.kind==='person'?'ミナのWORLD':state.world.tags.slice(0,3).map(escapeHTML).join(' × ')}<span class="world-interest-chips">${state.world.kind==='person'?'':state.world.tags.slice(3).length?' × '+state.world.tags.slice(3).map(escapeHTML).join('・'):''}</span></h2><p class="sub"><b>${state.world.members}人のWORLD</b></p><div class="tabs" role="tablist" aria-label="コンテンツの種類">${['すべて','記事','動画','音楽','投稿'].map(t=>`<button role="tab" aria-selected="${state.tab===t}" data-tab="${t}" class="${state.tab===t?'active':''}">${t}</button>`).join('')}</div><div role="tabpanel" aria-label="${state.tab}のコンテンツ">${items.filter(c=>state.tab==='すべて'||c.type===state.tab).map(worldItem).join('')||'<p class="empty">この種類の新しい好きは、まだありません。</p>'}</div><button class="profile-short" data-go="profile">${icon('mina')}<span>${state.world.kind==='person'?'ミナのプロフィールを見る':'このWORLDのミナさんを見る'}</span><span>›</span></button><p class="bottom-note">見ただけではMY WORLDは変わりません。</p>`,{backButton:false,active:'search'});}
  case 'why':{const world=state.detailOrigin;const n=worldCount(c,world);const both=Math.min(n,Math.round(n*14/24));return shell('なぜ、この世界に？',`${contentCard(c,'noop')}<details class="article-body"><summary>本文を読む</summary>${(Array.isArray(c.body)?c.body:[c.body||c.desc]).map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</details><div class="box recommendation-metric"><div class="metric">${icon('whyPeople')}<div><small>${world.kind==='person'?'ミナのWORLD':'このWORLDの'}</small><br><strong>${n}<span> / ${world.members}</span></strong><small> 人が好き</small></div></div><div class="bar"><span style="width:${n/world.members*100}%"></span></div><p class="metric-caption">このWORLDの${world.members}人中${n}人が好き</p></div><div class="box"><h3>好きな${n}人の傾向</h3><p class="category">公開プロフィールから</p>${[['美術','art',17],['小説','book',15],['お絵かき','artPalette',9]].map(([x,i,v])=>{const value=Math.min(n,Math.round(v*n/24));return `<div class="why-bars">${icon((i==='art'||i==='headphone')&&!state.interests.includes(x)?i:({art:'aboutArt',game:'aboutGame',headphone:'aboutHeadphone',building:'aboutBuilding',book:'aboutBook',mountain:'aboutMountain'}[i]||i))}<span>${x}</span><div class="bar"><span style="width:${value/(n||1)*100}%"></span></div><span>${value}人</span></div>`;}).join('')}</div><div class="box"><h3>入口の「${escapeHTML(world.entry)}」と両方好き</h3><div class="venn"><div class="venn-art">${c.id==='lamp'?icon('whyOverlap'):icon('book')+icon(c.icon)}</div><div><strong>${both}</strong> 人<small>同じ「好き」から<br>新しい出会いへ。</small></div></div></div>`,{active:state.detailSection||'search',foot:addButton(c)});}
  case 'added':return shell('FILTRIP',`<div class="success-icon">${icon('addedCheck')}</div><h2 class="success-title">MY WORLDに追加しました</h2>${contentCard(c,'noop')}<p class="success-description">${state.detailOrigin.id==='home-recommend'?'ホームのおすすめから保存しました':escapeHTML(state.origins[c.id]?.world.name||state.detailOrigin.name)+'の<br>WORLDから持ち帰りました'}</p><div class="journey"><div>${icon('whyPeople')}<strong>${state.detailOrigin.id==='home-recommend'?'RECOMMEND':'OTHER WORLD'}</strong><small>誰かの「好き」</small></div><span>→</span><div>${icon('book')}<strong>MY WORLD</strong><small>あなたの「好き」</small></div></div>`,{active:'mine',foot:primary('MY WORLDを見る','show-mine')+'<button class="secondary" data-action="continue-trip">'+(state.detailOrigin.id==='home-recommend'?'おすすめに戻る':'旅を続ける')+'</button>'});
  case 'mine':{const categoriesSelected=[...new Set(selectedWorks().map(w=>w.category))];return shell('MY FILTRIP',`<div class="my-profile">${selfAvatar()}<div class="chips">${[state.age,...state.interests].filter(Boolean).map(x=>`<span class="chip green">${x}</span>`).join('')}</div></div><div class="section-heading"><h3>MY WORLD</h3><button class="mini-link" data-action="edit-favorites">すべて見る ›</button></div>${categoriesSelected.length?`<div class="shelf">${categoriesSelected.map(id=>{const cat=categories.find(c=>c.id===id);const count=selectedWorks().filter(w=>w.category===id).length;return `<button data-action="shelf" data-id="${id}">${categoryIcon(cat.icon)}<strong>${cat.name}</strong><small>${count}件の好き</small></button>`;}).join('')}</div>`:'<button class="empty" data-action="edit-favorites">好きなものを選んで、自分の世界をつくる ＋</button>'}<div class="section-heading"><h3>FROM MY TRIPS</h3><span>${state.added.length}件</span></div><p class="sub">旅先から持ち帰ったもの</p>${state.added.length?[...state.added].reverse().map(id=>{const item=contentById(id);const source=state.origins[id];return `<article class="history-entry">${contentCard({...item,desc:source?.world.name+'のWORLDから'})}<span class="history-meta">${source?new Date(source.date).toLocaleDateString('ja-JP'):''}</span></article>`;}).join(''):'<div class="empty">旅先で見つけた「好き」が、ここに並びます。</div>'}`,{active:'mine',backButton:false,right:'<button data-action="settings" aria-label="設定">⚙</button>'});}
  case 'profile':return shell('プロフィール',`<div class="profile-head"><div class="avatar">${icon('mina')}</div><div><h2>ミナ</h2><div class="chips"><span class="chip">20代</span><span class="chip">大学生</span><span class="chip">美術</span><span class="chip">小説</span><span class="chip">お絵かき</span></div></div></div><div class="stat-grid"><div class="box"><span class="stat-label">公開した好き</span><span class="stat-bookmark" aria-hidden="true">${icon('statBookmark')}</span><strong>42<small>件</small></strong></div><div class="box"><span class="stat-label">共通点</span><span class="stat-overlap" aria-hidden="true">${icon('statOverlap')}</span><strong>35<small>%</small></strong></div></div><div class="section-heading"><h3>最近の好き</h3><button class="mini-link" data-action="profile-all">すべて見る ›</button></div><div class="profile-gallery">${['history','craft','soda'].map(contentById).map(c=>`<button data-action="detail" data-id="${c.id}">${thumb({...c,art:{history:'profileHistory',craft:'profileCraft',soda:'profileSoda'}[c.id]})}<strong>${c.title}</strong><small>${c.type}</small></button>`).join('')}</div><div id="profile-more" hidden>${['lamp','night','tools'].map(contentById).map(c=>contentCard(c)).join('')}</div><button class="primary" data-action="follow">${state.following?'✓ FOLLOWING WORLD':'FOLLOW WORLD'}</button><p class="follow-caption">${state.following?'ミナの新しい好きが、あなたのホームに届きます。':'この世界の新しい好きに出会う'}</p><button class="secondary" data-go="messages">メッセージ</button><p class="bottom-note">お互いにメッセージを許可しています。</p><button class="profile-world-link" data-action="profile-world">この人の世界を見る ›</button>`,{active:'search'});
  case 'messages':return shell('ミナ',`<div class="conversation-post"><div class="post-author">${icon('cat')}<span><strong>しめきり</strong><small>@deadline_404</small></span></div><p>${contentById('post').desc}</p><button class="mini-link" data-action="detail" data-id="post">投稿を見る ›</button></div>${conversationMessage('この投稿、今日の自分すぎる','10:24',true)}${conversationMessage('また誤字見つけた？','10:26',false)}${conversationMessage('提出後にPDF開いた自分が悪い笑','10:29',true)}${conversationMessage('見なきゃ平和だったのに笑','10:31',false)}${state.messages.map(t=>`<div class="message mine">${escapeHTML(t.text||t)}<time>${t.time||''}</time></div>`).join('')}`,{active:'messages',right:icon('mina'),foot:`<form class="message-form"><label class="sr-only" for="message-input">メッセージ</label><input id="message-input" placeholder="メッセージを入力…" value="${escapeHTML(state.draft)}" maxlength="300" autocomplete="off"><button type="submit" aria-label="メッセージを送信" ${state.draft.trim()?'':'disabled'}>➤</button></form>`});
  case 'video':return shell('動画を見る',`<div class="player-surface">${thumb(c.id==='repair'?{...c,art:'repairPlayer'}:c)}</div><h2 class="content-detail-title">${c.title}</h2><div class="creator-line">${avatar(c.personId||'repair-club','creator-avatar')}<div><strong>${c.by}</strong><small>動画チャンネル</small></div></div><div class="content-actions"><button data-action="like" aria-pressed="${state.liked.includes(c.id)}">${state.liked.includes(c.id)?'♥':'♡'}<span>いいね</span></button><button data-action="add" data-id="${c.id}">${state.added.includes(c.id)?'✓':'⊕'}<span>保存</span></button></div><p class="content-description">${c.desc}</p><div class="box people-content"><h3>この動画を好きな人</h3>${icon(c.id==='repair'?'repairAudience':'whyPeople',c.id==='repair'?'audience-art':'')}<p>このWORLDの${state.detailOrigin.members}人中<strong>${worldCount(c,state.detailOrigin)}人</strong>が好き</p><button class="mini-link" data-action="why-current">好きのつながりを見る ›</button></div>${relatedSection(c)}`,{active:state.detailSection||'search',foot:addButton(c)});
  case 'post':return shell('投稿を見る',`<div class="post-author detail-author">${avatar(c.personId,'post-avatar')}<span><strong>${escapeHTML(postAuthorName(c))}</strong><small>${escapeHTML(c.handle||c.by)} · 3時間前</small></span></div><p class="post-text">${c.desc}</p><div class="post-reactions"><button data-action="like" aria-pressed="${state.liked.includes(c.id)}">${state.liked.includes(c.id)?'♥':'♡'} ${c.n*4+3+(state.liked.includes(c.id)?1:0)}</button><span>↪ ${c.n}</span><span>コメント ${c.reply?1:0}</span></div>${c.reply?`<div class="post-reply"><div class="post-author">${icon('pudding')}<span><strong>おやつの記録</strong><small>@snackmemo · 2時間前</small></span></div><p>${escapeHTML(c.reply)}</p></div>`:''}<div class="box people-content">${icon('whyPeople')}<p>このWORLDの${state.detailOrigin.members}人中<strong>${worldCount(c,state.detailOrigin)}人</strong>が好き</p><button class="mini-link" data-action="why-current">好きのつながりを見る ›</button></div>`,{active:state.detailSection||'search',foot:addButton(c)});
  case 'music':return shell('音楽を聴く',`<div class="music-detail">${thumb(c)}<h2>${c.title}</h2><p class="sub">${c.by}</p><p>${c.desc}</p></div><div class="box people-content">${icon('whyPeople')}<p>このWORLDの${state.detailOrigin.members}人中<strong>${worldCount(c,state.detailOrigin)}人</strong>が好き</p><button class="mini-link" data-action="why-current">好きのつながりを見る ›</button></div>${relatedSection(c)}`,{active:state.detailSection||'search',foot:addButton(c)});
  case 'settings':return shell('設定',`<div class="settings-list"><button data-action="settings-about">あなたについて <span>›</span></button><button data-action="edit-favorites">好きなもの <span>›</span></button><button data-action="settings-quiz">性格診断 <span>›</span></button><button data-action="settings-sources">コンテンツの種類 <span>›</span></button></div>`,{active:'mine'});
  }
  state.screen='welcome';return screen();
}
function resultWorldCards(){const group={id:'readers',name:`${state.filters.interest==='指定なし'?'':state.filters.interest+'と'}${state.filters.favorite}が好きな人たち`,members:84,entry:state.filters.favorite,tags:Object.values(state.filters).filter(x=>x!=='指定なし'),kind:'group'};const cards=[{id:'readers',art:'worldBook',name:group.name,kind:'84人のWORLD',total:'1,248',tags:[state.filters.age,state.filters.gender,state.filters.job]},{id:'artists',art:'artPalette',name:'お絵かきをする大学生たち',kind:'68人のWORLD',total:'892',tags:['大学生','美術','創作']},{id:'mina',art:'mina',name:'ミナの世界',kind:'個人のWORLD',total:'42',tags:['20代','女性','大学生']}];if(state.sort==='好きが多い順')cards.sort((a,b)=>Number(b.total.replace(',',''))-Number(a.total.replace(',','')));if(state.sort==='個人のWORLDから')cards.reverse();return cards.map(r=>`<article class="world-result"><div class="result-top">${icon(r.art)}<div><h3>${escapeHTML(r.name)}</h3><div class="chips">${r.tags.filter(x=>x!=='指定なし').map(x=>`<span class="chip">${x}</span>`).join('')}</div><p>${r.kind}<br>公開された好き <strong>${r.total}</strong>件</p></div></div><button class="primary small" data-world="${r.id}">この世界を見る ›</button></article>`).join('');}
function selfAvatar(profile=state.profile){return Number.isInteger(profile.portraitIndex)&&profile.portraitIndex>=0&&profile.portraitIndex<8?FILTRIP_USER_AVATAR({id:'chosen-self',portraitIndex:profile.portraitIndex}):icon('you');}
function avatarPicker(){const current=profileForm().portraitIndex??-1;return `<details class="self-avatar-picker"><summary><span class="self-avatar-preview">${selfAvatar(profileForm())}</span><span>アイコンを選ぶ<small>あとから変更できます</small></span><span aria-hidden="true">⌄</span></summary><div class="self-avatar-options" role="group" aria-label="自分のアイコン">${Array.from({length:9},(_,n)=>n-1).map(i=>`<button type="button" data-self-avatar="${i}" aria-label="${i===-1?'はじめのアイコン':'アイコン '+(i+1)}" aria-pressed="${current===i}">${selfAvatar({portraitIndex:i})}</button>`).join('')}</div></details>`;}
function profileForm(){return state.profileDraft||state.profile;}
function invalidAge(){const age=Number(profileForm().age);return Boolean(profileForm().age)&&(!Number.isInteger(age)||age<1||age>120);}
function validProfile(){const p=profileForm();return p.nickname.trim().length>0&&Boolean(p.age)&&!invalidAge()&&p.job!=='';}
function typeTabs(active,attribute){return `<div class="tabs feed-tabs" role="tablist" aria-label="コンテンツの種類">${['すべて','音楽','動画','記事','投稿'].map(t=>`<button role="tab" aria-selected="${active===t}" class="${active===t?'active':''}" ${attribute}="${t}">${t}</button>`).join('')}</div>`;}
function matchContent(c,query){const hay=normalizeText([c.title,c.by,c.desc,...(c.tags||[])].join(' '));return normalizeText(query).split(/[\s　]+/).filter(Boolean).every(t=>hay.includes(t));}
function recommendation(c){const text=normalizeText([c.title,c.by,...(c.tags||[])].join(' '));let score=c.curated?8:0,reason='まだ知らない好きに出会う';for(const w of selectedWorks()){const hits=[w.categoryName,w.genre,w.title].filter(term=>term===w.categoryName?(c.tags||[]).some(t=>normalizeText(t)===normalizeText(term)):text.includes(normalizeText(term)));if(hits.length){score+=hits.length*5;reason='選んだ「'+hits[hits.length-1]+'」に関連';}}for(const id of state.added){const saved=contentById(id);const matches=(saved.tags||[]).filter(tag=>(c.tags||[]).includes(tag));if(matches.length){score+=matches.length*3;if(score>0)reason='保存した「'+matches[0]+'」から';}}for(const id of state.followIds)if((personLikes.get(id)||[]).includes(c.id)){score+=6;reason=personById(id).name+'さんの好きから';}return {score,reason};}
function homeItems(){const items=(state.homeMode==='my'?state.added.map(contentById):catalog.filter(c=>state.homeTab==='すべて'?state.sources.includes(c.type):true)).filter(c=>state.homeTab==='すべて'||c.type===state.homeTab).filter(c=>matchContent(c,state.homeQuery));if(state.homeMode==='my')return items.sort((a,b)=>state.added.indexOf(b.id)-state.added.indexOf(a.id));const pools=new Map(['記事','音楽','動画','投稿'].map(type=>[type,items.filter(c=>c.type===type).map(c=>({c,...recommendation(c)})).sort((a,b)=>b.score-a.score)]));const output=[],recent=[];while(output.length<items.length)for(const pool of pools.values()){if(!pool.length)continue;let index=pool.findIndex(item=>!recent.slice(-3).includes(item.c.genre));if(index<0)index=0;const item=pool.splice(index,1)[0];output.push(item.c);recent.push(item.c.genre);}return output;}
function feedCard(c){return `<article class="feed-item ${c.type==='投稿'?'feed-post':''}" data-content-id="${c.id}">${state.screen==='home'&&state.homeMode==='recommend'?`<p class="recommend-reason">${escapeHTML(recommendation(c).reason)}</p>`:''}${c.type==='投稿'?postPreview(c):contentCard(c)}<div class="feed-meta"><span class="publisher-static">${c.type==='投稿'?sourceBadge(c):publisherLine(c,true)}</span>${addButton(c,true)}</div></article>`;}

function pagedFeed(items,limit,moreAction){return `${items.slice(0,limit).map(feedCard).join('')}${!items.length?'<div class="empty feed-empty">見つかりませんでした。<br>キーワードや種類を変えてみてください。</div>':''}${items.length>limit?`<button class="secondary load-more" data-action="${moreAction}">もっと読む <small>${Math.min(limit,items.length)} / ${items.length}</small></button>`:''}`;}
function queryTokens(text){let q=normalizeText(text).replace(/が好きな人たち|が好きな人|好きな人|が好き|好き|な人たち|な人|探してください|探して|に興味がある|に詳しい/g,' ').trim();const known=[...new Set([...people.flatMap(p=>[...(p.tags||[]),p.name,p.job,p.region]),...catalog.flatMap(c=>c.tags||[])].filter(Boolean))].sort((a,b)=>b.length-a.length);const found=[];for(const word of known){const term=normalizeText(word);if(term.length>1&&q.includes(term)){found.push(term);q=q.split(term).join(' ');}}const rest=q.replace(/(\d+)代/g,(_,n)=>{found.push(`${n}代`);return ' ';}).replace(/(?:の|と|で|を|に|が|も|は|な|人|たち)/g,' ').split(/[\s、,・/]+/).filter(Boolean);return [...new Set([...found,...rest])];}
const categoryPatterns={music:/音楽|ジャズ|ロック|クラシック|作曲|ピアノ|鍵盤|電子音/,video:/動画|映像|ゲーム実況|旅|料理|ものづくり/,game:/ゲーム|rpg|インディー|hollow knight/,film:/映画|ミニシアター|シネマ/,book:/読書|小説|本屋|書店|エッセイ|詩|短歌/,art:/アート|美術|デザイン|写真|お絵かき|創作|ドット絵/};
function personMatchesCategory(p,category){if(!category)return true;const text=normalizeText([p.bio,...(p.tags||[])].join(' '));return categoryPatterns[category]?.test(text)||false;}

function genreChoices(){return [...new Set([...(state.searchCategories.length?categories.filter(c=>state.searchCategories.includes(c.id)).flatMap(c=>Object.keys(c.genres)):['ロック','ジャズ','クラシック','映画','読書','ゲーム','アート','写真','料理','旅','ファッション','ゴスロリ','ものづくり','科学']),...state.searchFilters.genres])];}
function multiChoices(key,choices){return `<div class="multi-choice-list">${choices.map(value=>`<button type="button" data-search-multi="${key}" data-value="${escapeHTML(value)}" aria-pressed="${state.searchFilters[key].includes(value)}">${escapeHTML(value)}</button>`).join('')}</div>`;}
function searchValidation(){const f=state.searchFilters,lo=Number(f.ageMin),hi=Number(f.ageMax);if([f.ageMin,f.ageMax].some(v=>v!==''&&(!Number.isInteger(Number(v))||Number(v)<1||Number(v)>120)))return '年齢は1〜120の整数で指定してください。';if(f.ageMin&&f.ageMax&&lo>hi)return '年齢の下限を上限以下にしてください。';return '';}
/* 人物検索: 入力文の中にデータの言葉(タグ・職業・地域・作品名・カテゴリなど)が含まれていれば当たり。多く当たる人ほど上に並べる。 */
const personCorpusCache=new Map();
function personCorpus(p){if(!personCorpusCache.has(p.id))personCorpusCache.set(p.id,normalizeText([p.name,p.bio,p.job,p.region,...(p.tags||[])].join(' ')));return personCorpusCache.get(p.id);}
function personTagText(p){return normalizeText([...(p.tags||[]),p.name,p.job,p.region].join(' '));}
// 一致の強さ: 職業・地域・タグでの一致(タグが多いほど強い)が最も強く、自己紹介文だけの一致は弱い。
function tagStrength(p,re){const n=(p.tags||[]).filter(t=>re.test(normalizeText(t))).length;return n?Math.min(1,.5+.25*n):(re.test(normalizeText(p.bio||''))?.3:0);}
function termStrength(p,term){if(!personTagText(p).includes(term))return personCorpus(p).includes(term)?.3:0;const n=(p.tags||[]).filter(t=>normalizeText(t).includes(term)).length;const exact=[...(p.tags||[]),p.job,p.region,p.name].some(t=>normalizeText(t)===term);return 1+(exact?.5:0)+.1*Math.min(5,Math.max(0,n-1));}
let searchDictCache=null;
function searchDictionary(){if(searchDictCache)return searchDictCache;const words=new Map();const add=(w,attr)=>{const t=normalizeText(w);if(t.length>1&&!words.has(t))words.set(t,{label:String(w),attr:!!attr});};for(const p of people){(p.tags||[]).forEach(w=>w&&add(w));add(p.name);add(p.job,true);add(p.region,true);}for(const c of catalog)(c.tags||[]).forEach(add);for(const cat of categories){add(cat.name);for(const [genre,titles] of Object.entries(cat.genres)){add(genre);titles.forEach(add);}}return searchDictCache=[...words].sort((a,b)=>b[0].length-a[0].length);}
// 「聴く」「本好き」などの言い回しから、カテゴリ・職業の言葉を拾う。
const searchTriggers=[
 {label:'音楽',q:/音楽|聴く|聞く|演奏|楽器|作曲/,test:p=>tagStrength(p,categoryPatterns.music)},
 {label:'本',q:/読書|小説|読む|(?<!日)本(?!当)/,test:p=>tagStrength(p,categoryPatterns.book)},
 {label:'映画',q:/映画|シネマ|観る|上映/,test:p=>tagStrength(p,categoryPatterns.film)},
 {label:'ゲーム',q:/ゲーム|遊ぶ|rpg|実況/,test:p=>tagStrength(p,categoryPatterns.game)},
 {label:'絵・アート',q:/絵|描く|描い|イラスト|アート|美術|デザイン/,test:p=>tagStrength(p,/絵|イラスト|アート|美術|デザイン|お絵かき|描|ドット絵|印刷/)},
 {label:'写真',q:/写真|撮る|カメラ/,test:p=>tagStrength(p,/写真|フィルム|カメラ|撮/)},
 {label:'料理',q:/料理|お菓子|ごはん|台所/,test:p=>tagStrength(p,/料理|菓子|台所|調理/)},
 {label:'喫茶',q:/喫茶|カフェ|コーヒー/,test:p=>tagStrength(p,/喫茶|カフェ|コーヒー/)},
 {label:'旅',q:/旅|散歩|ローカル線/,test:p=>tagStrength(p,/旅|散歩|ローカル線/)},
 {label:'科学',q:/科学|実験|天文|星空/,test:p=>tagStrength(p,/科学|実験|天文|星/)},
 {label:'ファッション',q:/服|ファッション|古着|おしゃれ/,test:p=>tagStrength(p,/服|ファッション|古着|服飾|装い|ゴスロリ/)},
 {label:'学生',attr:true,q:/学生|学部生|大学院/,test:p=>/学生|大学院|学部/.test(normalizeText(p.job||''))?1:0},
 {label:'社会人',attr:true,q:/社会人/,test:p=>/会社員|営業|事務|エンジニア|販売員|編集者|スタッフ|デザイナー/.test(normalizeText(p.job||''))?1:0}
];
const searchConceptCache=new Map();
function searchConcepts(text){const key=normalizeText(text);if(searchConceptCache.has(key))return searchConceptCache.get(key);const hits=new Map();const addHit=(label,test,attr)=>{if(!hits.has(label))hits.set(label,{label,tests:[],factor:1});const h=hits.get(label);h.tests.push(test);if(attr)h.factor=.8;};let rest=key;
 for(const [term,{label,attr}] of searchDictionary()){if(rest.includes(term)){rest=rest.split(term).join(' ');addHit(label,p=>termStrength(p,term),attr);for(const t of searchTriggers){const m=term.match(t.q);if(m&&m[0]===term)addHit(label,t.test,t.attr);}}}
 for(const t of searchTriggers){if(t.q.test(rest)){addHit(t.label,t.test,t.attr);rest=rest.replace(new RegExp(t.q.source,'g'),' ');}}
 rest=rest.replace(/(\d+)代/g,(_,n)=>{addHit(`${n}代`,p=>Math.floor(p.age/10)*10===Number(n)?1:0,true);return ' ';});
 const boosts=rest.replace(/が好きな人たち|が好きな人|好きな人|好きな|好き|な人たち|な人|の人たち|の人|探してください|探して|に興味がある|に詳しい/g,' ').replace(/[のとでをにがもはな人たち]/g,' ').split(/[\s、,・/。？?！!]+/).filter(w=>w.length>1||/^[\u4e00-\u9fff]$/.test(w)).map(w=>({label:w,test:p=>personCorpus(p).includes(w)?.1:0}));
 const result={hits:[...hits.values()],boosts};searchConceptCache.set(key,result);return result;}
function personMatch(p,concepts){const labels=[];let score=0,interest=false;for(const h of concepts.hits){const w=Math.max(...h.tests.map(t=>t(p)));if(w>0){labels.push(h.label);score+=w*h.factor;if(h.factor===1)interest=true;}}if(score)for(const b of concepts.boosts){const w=b.test(p);if(w>0){labels.push(b.label);score+=w;}}return {labels,score,interest};}
function matchNote(p){const q=(state.personQuery||'').trim();if(!q)return '';let labels=personMatch(p,searchConcepts(q)).labels;if(!labels.length){const corpus=personCorpus(p);labels=queryTokens(q).filter(t=>/^\d+代$/.test(t)?Math.floor(p.age/10)*10===parseInt(t):corpus.includes(t));}return labels.length?'一致: '+[...new Set(labels)].slice(0,4).join('・'):'';}
function searchExampleButtons(){return '<div class="example-list">'+['夜に音楽を聴く人','本好きの学生','京都の人'].map(t=>`<button class="chip" data-action="search-example" data-text="${t}">${t}</button>`).join('')+'</div>';}
function searchPeople(){if(searchValidation())return [];const generic=/^([ぁ-ん]|ひと|こと|もの|とか|など|ください|お願い|教えて|知りたい|会いたい|いる|ある|する|して|したい|です|ます)$/;const terms=queryTokens(state.personQuery).filter(t=>!generic.test(t));const f=state.searchFilters;const work=works.find(w=>normalizeText(w.title)===normalizeText(state.workQuery));
 const termsMatch=p=>terms.every(t=>/^\d+代$/.test(t)?Math.floor(p.age/10)*10===parseInt(t):personCorpus(p).includes(t));
 const otherFilters=p=>{const liked=(personLikes.get(p.id)||[]).map(contentById);const corpus=personCorpus(p);if(state.workQuery.trim()&&!(work?corpus.includes(normalizeText(work.title)):corpus.includes(normalizeText(state.workQuery.trim()))||liked.some(c=>matchContent(c,state.workQuery))))return false;if(state.searchCategories.length&&!state.searchCategories.some(category=>personMatchesCategory(p,category)))return false;if(f.ageMin&&p.age<Number(f.ageMin)||f.ageMax&&p.age>Number(f.ageMax))return false;if(f.job&&window.FILTRIP_PROFILE.normalizeJob(p.job)!==f.job||f.region&&window.FILTRIP_PROFILE.normalizeRegion(p.region)!==f.region)return false;if(f.genre&&!corpus.includes(normalizeText(f.genre)))return false;if(f.genres.length&&!f.genres.some(genre=>corpus.includes(normalizeText(genre))))return false;if(f.contentTypes.length&&!liked.some(c=>f.contentTypes.includes(c.type)))return false;if(f.followingOnly&&!state.followIds.includes(p.id))return false;return true;};
 const strict=people.filter(p=>termsMatch(p)&&otherFilters(p));
 // 従来どおり全部の言葉に当たる人を先頭に。従来の結果は消さない。
 if(!(state.personQuery||'').trim())return strict;
 if(!terms.length)return []; // 「好き」「の」「人」などの汎用語だけ: 意味のある語が無いので0人
 const concepts=searchConcepts(state.personQuery);
 if(!concepts.hits.length)return strict;
 const rank=list=>list.map((p,i)=>({p,i,s:personMatch(p,concepts).score})).sort((a,b)=>b.s-a.s||a.i-b.i).map(x=>x.p);
 if(strict.length&&concepts.hits.length<2)return rank(strict);
 // 言葉の一部にだけ当たる人も、当たった言葉の数が多い順に続ける。
 const strictIds=new Set(strict.map(p=>p.id));
 const extra=people.map((p,i)=>({p,i,...personMatch(p,concepts)})).filter(x=>x.score>0&&(!strict.length||x.interest)&&!strictIds.has(x.p.id)&&otherFilters(x.p)).sort((a,b)=>b.score-a.score||a.i-b.i).map(x=>x.p);
 return [...rank(strict),...extra];}
function resultPeople(){return state.searchResultIds.map(personById);}
function searchSummary(){return [state.personQuery,state.workQuery,state.searchFilters.ageMin?state.searchFilters.ageMin+'歳以上':'',state.searchFilters.ageMax?state.searchFilters.ageMax+'歳以下':'',state.searchFilters.contentTypes.join('・'),state.searchFilters.genres.join('・'),state.searchFilters.followingOnly?'フォロー中':'',state.searchCategories.map(id=>categories.find(c=>c.id===id)?.name).filter(Boolean).join('・'),state.searchFilters.job,state.searchFilters.region,state.searchFilters.genre].filter(Boolean).join(' / ')||'好きなものからつながる人たち';}
function resultGroup(){const ids=state.searchResultIds;return {id:'search-group',name:searchSummary(),members:ids.length,kind:'group',entry:state.workQuery||state.personQuery||'好きなもの',tags:[state.searchFilters.job,state.searchFilters.region,state.searchFilters.genre].filter(Boolean),personIds:ids,contentIds:[...new Set(ids.flatMap(id=>personLikes.get(id)||[]))]};}
function personRow(p,mode='profile',note=''){return `<button class="person-row" ${mode==='chat'?`data-v3chat="${p.id}"`:`data-v3profile="${p.id}"`}>${avatar(p)}<span><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML([p.job,p.region].filter(Boolean).join(' · '))}</small><span class="person-tags">${(p.tags||[]).slice(0,3).map(t=>`<span>${escapeHTML(t)}</span>`).join('')}</span>${note?`<small class="match-note">${escapeHTML(note)}</small>`:''}</span><span aria-hidden="true">›</span></button>`;}
function threadMessages(id){return id==='mina'?[{text:'この投稿、今日の自分すぎる',time:'10:24',mine:true},{text:'また誤字見つけた？',time:'10:26',mine:false},{text:'提出後にPDF開いた自分が悪い笑',time:'10:29',mine:true},{text:'見なきゃ平和だったのに笑',time:'10:31',mine:false},...(state.threads[id]||[])]:state.threads[id]||[];}
function v3Message(m,p){return `<div class="message-row ${m.mine?'mine':'received'}">${m.mine?'':`<div class="message-avatar">${avatar(p)}</div>`}<div class="message ${m.mine?'mine':''}" aria-label="${m.mine?'あなた':escapeHTML(p.name)}のメッセージ">${escapeHTML(m.text)}<time>${escapeHTML(m.time)}</time></div></div>`;}
function screen(){const p=personById(state.profileId);if(['article','video','post','music'].includes(state.screen))return renderContentDetail(contentById(state.detail),state.screen);if(state.screen==='likers')return shell('このコンテンツが好きな人',`<p class="sub">${escapeHTML(contentById(state.detail).title)}</p>${state.detailOrigin.personIds.filter(id=>(personLikes.get(id)||[]).includes(state.detail)).map(id=>personRow(personById(id))).join('')||'<p class="empty">まだ公開された好きはありません。</p>'}`,{active:state.detailSection||'search'});switch(state.screen){
case 'about':return shell('あなたについて',`${state.editing==='about'?'':'<div class="progress-line"><span style="width:33%"></span></div>'}<h2>${state.editing==='about'?'プロフィールを編集':'まずは、あなたのこと。'}</h2>${avatarPicker()}<form class="basic-profile" novalidate><label>ニックネーム <span>必須</span><input id="profile-nickname" data-profile="nickname" autocomplete="nickname" maxlength="24" value="${escapeHTML(profileForm().nickname)}" placeholder="ニックネームを入力"></label><div class="profile-form-stack"><label>年齢 <span>必須</span><input id="profile-age" data-profile="age" type="number" inputmode="numeric" min="1" max="120" value="${escapeHTML(profileForm().age)}" placeholder="年齢を入力" aria-describedby="age-error" aria-invalid="${invalidAge()}"><small class="field-error" id="age-error" ${invalidAge()?'':'hidden'}>1〜120の整数で入力してください</small></label><label>職業 <span>必須</span><select id="profile-job" data-profile="job" class="${profileForm().job?'':'is-empty'}">${window.FILTRIP_PROFILE.jobOptions(profileForm().job)}</select></label></div><label>都道府県 <span>任意</span><select id="profile-region" data-profile="region" class="${profileForm().region?'':'is-empty'}">${window.FILTRIP_PROFILE.regionOptions(profileForm().region)}</select></label><label>性別 <span>任意</span><select data-profile="gender" class="${profileForm().gender?'':'is-empty'}"><option value="">選択しない</option>${['女性','男性','その他'].map(x=>`<option ${profileForm().gender===x?'selected':''}>${x}</option>`).join('')}</select></label></form>`,{noNav:true,right:state.editing==='about'?'':'1 / 3',foot:primary(state.editing==='about'?'変更を保存':'次へ',state.editing==='about'?'about-save':'about-next',!validProfile())});
case 'home':{const items=homeItems();return shell('MY WORLD',`<div class="home-modes" role="tablist" aria-label="ホームの表示"><button data-home-mode="my" role="tab" aria-selected="${state.homeMode==='my'}">保存した好き</button><button data-home-mode="recommend" role="tab" aria-selected="${state.homeMode==='recommend'}">RECOMMEND</button></div><label class="feed-search">${functionalIcon('search')}<input id="home-query" value="${escapeHTML(state.homeQuery)}" placeholder="作品・作者・キーワードを検索" aria-label="ホームのコンテンツを検索"></label>${typeTabs(state.homeTab,'data-home-tab')}<button class="discovery home-explore" data-action="home-search">${functionalIcon('people')}<span>誰かの世界を探す</span><span>›</span></button><div class="feed-heading"><strong>${state.homeMode==='my'?'あなたが持ち帰った好き':'あなたへのおすすめ'}</strong><span id="home-count">${items.length}件</span></div><div id="home-feed">${state.homeMode==='my'&&!state.added.length?'<div class="empty">気に入ったコンテンツを追加すると、ここに並びます。<button class="text-button" data-home-mode="recommend">おすすめを見る ›</button></div>':pagedFeed(items,state.homeLimit,'home-more')}</div>`,{backButton:false,active:'home',right:'<button data-action="settings" aria-label="設定">'+functionalIcon('settings')+'</button>'});}
case 'search':{return shell('EXPLORE',`<h2>気になる人を、言葉で。</h2><label class="people-query-label"><span class="sr-only">探したい人の特徴</span><textarea id="person-query" placeholder="興味・価値観・暮らし方など" rows="2">${escapeHTML(state.personQuery)}</textarea></label><p class="field-help">好きなもの・職業・地域を自由に組み合わせて探せます。</p><label class="work-query-label"><strong>好きな作品から探す</strong><input id="work-query" value="${escapeHTML(state.workQuery)}" placeholder="作品名・作者・ジャンル" maxlength="80"></label><p class="selection-caption">カテゴリ <span>複数選択可</span></p><div class="search-category-chips" aria-label="好きなカテゴリ">${categories.map(c=>`<button data-search-category="${c.id}" aria-pressed="${state.searchCategories.includes(c.id)}">${functionalIcon(c.icon)}${c.name}</button>`).join('')}</div>${state.workSearchHistory?.length?`<p class="selection-caption">最近検索した作品</p><div class="selected-entries">${state.workSearchHistory.map((title,i)=>`<button class="chip" data-search-history="${i}">${escapeHTML(title)}</button>`).join('')}</div>`:''}<details class="advanced-search" ${state.searchDetailsOpen?'open':''}><summary>条件をくわしく選ぶ <span>${state.searchDetailsOpen?'−':'＋'}</span></summary><div class="search-detail-fields"><div class="profile-form-row"><label>年齢の下限<input type="number" min="1" max="120" data-search-filter="ageMin" aria-describedby="search-error" value="${state.searchFilters.ageMin}" placeholder="指定なし"></label><label>年齢の上限<input type="number" min="1" max="120" data-search-filter="ageMax" aria-describedby="search-error" value="${state.searchFilters.ageMax}" placeholder="指定なし"></label></div><p id="search-error" class="field-error" role="status" ${searchValidation()?'':'hidden'}>${searchValidation()}</p><label>職業<select data-search-filter="job">${window.FILTRIP_PROFILE.jobOptions(state.searchFilters.job,'指定なし')}</select></label><label>都道府県<select data-search-filter="region">${window.FILTRIP_PROFILE.regionOptions(state.searchFilters.region,'指定なし')}</select></label><fieldset class="multi-filter"><legend>ジャンル・趣味 <small>複数選択可</small></legend>${multiChoices('genres',genreChoices())}</fieldset><p class="field-help">同じ項目の中では、どれかに当てはまる人を探します。</p><label>追加のキーワード<input data-search-filter="genre" value="${escapeHTML(state.searchFilters.genre)}" placeholder="趣味や関心のキーワード"></label><fieldset class="multi-filter"><legend>好きなコンテンツの種類 <small>複数選択可</small></legend>${multiChoices('contentTypes',['音楽','動画','記事','投稿'])}</fieldset><label class="check-label"><input type="checkbox" data-search-filter="followingOnly" ${state.searchFilters.followingOnly?'checked':''}>フォローしている人だけ</label><button class="text-button" data-action="clear-search-filters">詳細条件をクリア</button></div></details>`,{active:'search',foot:primary('FIND THE WORLD','search-run',Boolean(searchValidation()))});}
case 'results':{const found=resultPeople();return shell('WORLDS',`<p class="search-echo">${escapeHTML(searchSummary())}</p><div class="results-summary"><strong>${found.length}<small>人</small></strong><span>${found.length?'条件に合う世界が見つかりました':'条件に合う人はいませんでした'}</span></div>${!found.length?'<div class="empty"><h3>ぴったりの人は、まだ見つかりません。</h3><p>言葉を短くしたり、条件を少なくして探してみてください。</p><p class="example-caption">こんな言葉で探せます</p>'+searchExampleButtons()+'<button class="secondary" data-go="search">条件を見直す</button></div>':`${found.length>1?`<article class="world-result"><div class="result-top">${functionalIcon('people')}<div><h3>${escapeHTML(searchSummary())}</h3><p>${found.length}人の「好き」を一緒に見る</p></div></div><button class="primary" data-action="open-result-world">この人たちの世界を見る ›</button></article>`:''}<h3>一人ひとりのWORLD</h3>${found.slice(0,state.peopleLimit||24).map(p=>personRow(p,'profile',matchNote(p))).join('')}${found.length>(state.peopleLimit||24)?'<button class="secondary" data-action="people-more">もっと見る</button>':''}`}`,{active:'search'});}
case 'world':{let ids=state.world.contentIds||catalog.map(c=>c.id);let items=ids.map(contentById).filter(c=>state.tab==='すべて'||c.type===state.tab);return shell('FILTRIP',`<div class="trip-banner"><span><small>NOW TRIPPING</small>${state.world.kind==='person'?escapeHTML(state.world.name)+'の世界':'他者の世界を閲覧中'}</span><button data-go="mine">自分に戻る ›</button></div><h2 class="world-title">${escapeHTML(state.world.name)}${state.world.kind==='person'?'のWORLD':''}</h2><p class="sub">${state.world.members}人のWORLD · ${ids.length}件の好き</p><div class="chips world-interest-chips">${state.world.tags.slice(0,5).map(t=>`<span class="chip">${escapeHTML(t)}</span>`).join('')}</div>${typeTabs(state.tab,'data-tab')}<div class="world-feed" role="tabpanel">${items.slice(0,state.worldLimit).map(c=>worldItem(c)).join('')||'<p class="empty">この種類の好きは、まだありません。</p>'}</div>${items.length>state.worldLimit?'<button class="secondary" data-action="world-more">もっと読む</button>':''}${state.world.kind==='person'?`<button class="profile-short" data-v3profile="${state.world.id}">${avatar(state.world.id)}<span>${escapeHTML(state.world.name)}のプロフィールを見る</span><span>›</span></button>`:''}`,{active:'search'});}
case 'profile':{const liked=(personLikes.get(p.id)||[]).map(contentById);const follows=state.followIds.includes(p.id);const mutual=state.followerIds.includes(p.id);const common=liked.filter(c=>state.added.includes(c.id)).length;return shell('プロフィール',`<div class="profile-head"><div class="avatar">${avatar(p)}</div><div><h2>${escapeHTML(p.name)}</h2><div class="chips">${[p.age+'歳',p.job,p.region].filter(Boolean).map(t=>`<span class="chip">${escapeHTML(t)}</span>`).join('')}</div></div></div><p class="profile-bio">${escapeHTML(p.bio)}</p><div class="chips">${(p.tags||[]).map(t=>`<span class="chip green">${escapeHTML(t)}</span>`).join('')}</div><div class="stat-grid"><div class="box"><span class="stat-label">公開した好き</span><span class="stat-bookmark">${icon('statBookmark')}</span><strong>${liked.length}<small>件</small></strong></div><div class="box"><span class="stat-label">共通の好き</span><span class="stat-overlap">${icon('statOverlap')}</span><strong>${common}<small>件</small></strong></div></div><div class="section-heading"><h3>最近の好き</h3><button class="mini-link" data-action="profile-world">すべて見る ›</button></div><div class="profile-gallery">${liked.slice(0,3).map(c=>`<button data-action="detail" data-id="${c.id}">${thumb(c)}<strong>${escapeHTML(c.title)}</strong><small>${c.type}</small></button>`).join('')}</div><button class="primary" data-action="follow">${follows?'✓ フォロー中':'FOLLOW WORLD'}</button><button class="secondary" data-action="profile-message" ${follows||mutual?'':'disabled'}>メッセージ</button>${!follows&&!mutual?'<p class="bottom-note">フォローするとメッセージを送れます。</p>':''}<button class="profile-world-link" data-action="profile-world">この人の世界を見る ›</button>`,{active:'search'});}
case 'mine':{const selected=[...new Set(selectedWorks().map(w=>w.category))];return shell('MY FILTRIP',`<div class="my-profile-card"><div class="avatar">${selfAvatar()}</div><div><h2>${escapeHTML(state.profile.nickname||'あなた')}</h2><p>${escapeHTML([state.profile.age?state.profile.age+'歳':'',state.profile.job,state.profile.region].filter(Boolean).join(' · '))}</p><button class="mini-link" data-action="settings-about">プロフィールを編集</button></div></div><div class="relationship-stats"><button data-people-list="following"><strong>${state.followIds.length}</strong>フォロー</button><button data-people-list="followers"><strong>${state.followerIds.length}</strong>フォロワー</button></div><div class="section-heading"><h3>MY WORLD</h3><button class="mini-link" data-action="edit-favorites">好きなものを編集 ›</button></div><div class="shelf">${selected.map(id=>{const cat=categories.find(c=>c.id===id);return cat?`<button data-action="shelf" data-id="${id}">${categoryIcon(cat.icon)}<strong>${cat.name}</strong><small>${selectedWorks().filter(w=>w.category===id).length}件</small></button>`:'';}).join('')||'<p class="sub">まずは好きなものを選んでみましょう。</p>'}</div><div class="section-heading"><h3>FROM MY TRIPS</h3><span>${state.added.length}件</span></div>${[...state.added].reverse().slice(0,state.mineLimit||24).map(id=>{const c=contentById(id);return `<article class="history-entry">${contentCard({...c,desc:savedOriginLabel(state.origins[id]?.world)})}<div class="history-meta-row"><span class="history-meta">${new Date(state.origins[id]?.date||Date.now()).toLocaleDateString('ja-JP')}</span><button class="mini-link" data-action="remove-save" data-id="${c.id}" aria-label="${escapeHTML(c.title)}の保存を解除">保存を解除</button></div></article>`;}).join('')||'<div class="empty">旅先で見つけた好きが、ここに並びます。</div>'}${state.added.length>(state.mineLimit||24)?'<button class="secondary" data-action="mine-more">もっと読む</button>':''}`,{active:'mine',backButton:false,right:'<button data-action="settings" aria-label="設定">'+functionalIcon('settings')+'</button>'});}
case 'people-list':{const ids=state.listKind==='followers'?state.followerIds:state.followIds;return shell(state.listKind==='followers'?'フォロワー':'フォロー',`<p class="sub">${ids.length}人</p>${ids.map(id=>personRow(personById(id))).join('')||'<div class="empty">気になる人のWORLDをフォローすると、ここに並びます。<button class="secondary" data-go="search">人を探す</button></div>'}`,{active:'mine'});}
case 'messages':{const ids=Object.keys(state.threads).sort((a,b)=>(state.threads[b].at(-1)?.sentAt||0)-(state.threads[a].at(-1)?.sentAt||0));return shell('メッセージ',`<div class="section-heading"><h2>会話</h2><button class="mini-link" data-action="new-message">新しいメッセージ ＋</button></div><div class="thread-list">${ids.map(id=>{const who=personById(id),last=threadMessages(id).at(-1);return `<button class="thread-row" data-v3chat="${id}">${avatar(who)}<span><strong>${escapeHTML(who.name)}</strong><small>${escapeHTML(last?.text||'会話をはじめましょう')}</small></span><time>${escapeHTML(last?.time||'')}</time></button>`;}).join('')||'<div class="empty">フォローした人との会話が、ここに並びます。</div>'}</div>`,{active:'messages',backButton:false});}
case 'contacts':{const ids=[...new Set([...state.followIds,...state.followerIds])];return shell('新しいメッセージ',`<p class="sub">フォローしている人・あなたをフォローしている人</p>${ids.map(id=>personRow(personById(id),'chat')).join('')||'<div class="empty">人をフォローして、好きなものの話をはじめましょう。</div>'}`,{active:'messages'});}
case 'thread':{const who=personById(state.chatId),draft=state.drafts[state.chatId]||'';return shell(who.name,`<button class="conversation-person" data-v3profile="${who.id}">${avatar(who)}<span>プロフィールを見る ›</span></button>${window.FILTRIP_PRESENTING&&state.storySharedContent?'<div class=shared-topic><small>話題のコンテンツ</small>'+contentCard(contentById(state.storySharedContent),'noop')+'</div>':''}${threadMessages(who.id).map(m=>v3Message(m,who)).join('')||'<div class="empty">好きなものの話から、会話をはじめてみましょう。</div>'}`,{active:'messages',right:avatar(who),foot:`<form class="message-form" data-v3-thread><label class="sr-only" for="thread-input">メッセージ</label><textarea id="thread-input" rows="1" placeholder="メッセージを入力…" maxlength="500" autocomplete="off">${escapeHTML(draft)}</textarea><button type="submit" aria-label="メッセージを送信" ${draft.trim()?'':'disabled'}>${functionalIcon('send')}</button></form>`});}
case 'why':{if(!state.detailOrigin.personIds)return legacyScreen();const c=contentById(state.detail),world=state.detailOrigin,liked=world.personIds.filter(id=>(personLikes.get(id)||[]).includes(c.id)).map(personById);const counts=new Map();for(const person of liked)for(const tag of new Set(person.tags||[]))counts.set(tag,(counts.get(tag)||0)+1);const ranked=[...counts].sort((a,b)=>b[1]-a[1]).slice(0,3);return shell('なぜ、この世界に？',`${contentCard(c,'noop')}${c.type==='記事'?`<details class="article-body"><summary>本文を読む</summary>${(Array.isArray(c.body)?c.body:[c.body||c.desc]).map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</details>`:''}<div class="box recommendation-metric"><div class="metric">${functionalIcon('people')}<div><small>このWORLDの</small><br><strong>${liked.length}<span> / ${world.members}</span></strong><small> 人が好き</small></div></div><div class="bar"><span style="width:${liked.length/(world.members||1)*100}%"></span></div></div><div class="box"><h3>好きな人の共通点</h3>${ranked.map(([tag,n])=>`<div class="why-bars">${functionalIcon('people')}<span>${escapeHTML(tag)}</span><div class="bar"><span style="width:${n/(liked.length||1)*100}%"></span></div><span>${n}人</span></div>`).join('')||'<p class="sub">まだ共通点はありません。</p>'}</div><div class="box"><h3>${world.id==='home-recommend'?'おすすめに表示した理由':'この世界への入口'}</h3><p>${world.id==='home-recommend'?escapeHTML(recommendation(c).reason):world.kind==='person'?escapeHTML(world.name)+'さんが公開している好きから見つけたコンテンツです。':'「'+escapeHTML(world.entry)+'」で見つかった'+world.members+'人のうち、'+liked.length+'人がこのコンテンツを好きです。'}</p></div>`,{active:state.detailSection||'search',foot:addButton(c)});}
default:return legacyScreen();
}}
function v3Action(name,button){switch(name){
case 'detail-likers':go('likers');return true;
case 'content-likers':{const id=button.dataset.id||state.detail;state.detailOrigin=currentWorld(id);state.detail=id;go('likers');return true;}
case 'source-open':window.FILTRIP_APP_UI.openSource(contentById(button.dataset.id||state.detail));return true;
case 'remove-save':removeSaved(button.dataset.id);return true;
case 'undo-save':undoSaved();return true;
case 'about-next':case 'about-save':if(validProfile()){state.profile={...profileForm(),nickname:profileForm().nickname.trim(),region:profileForm().region.trim()};state.profileDraft=null;state.age=Math.floor(Number(state.profile.age)/10)*10+'代';if(name==='about-save'){state.editing=null;go('mine');}else{state.favoriteMode='onboarding';go('favorites',{guided:true});}}return true;
case 'home-more':state.homeLimit+=24;render(true);return true;
case 'world-more':state.worldLimit+=24;render(true);return true;
case 'mine-more':state.mineLimit=(state.mineLimit||24)+24;render(true);return true;
case 'people-more':state.peopleLimit=(state.peopleLimit||24)+24;render(true);return true;
case 'search-example':state.personQuery=button.dataset.text||'';state.workQuery='';state.searchCategories=[];state.searchFilters=newState().searchFilters;state.searchResultIds=searchPeople().map(p=>p.id);state.peopleLimit=24;render();return true;
case 'search-run':if(searchValidation())return true;if(state.workQuery.trim())state.workSearchHistory=[state.workQuery.trim(),...(state.workSearchHistory||[]).filter(t=>t!==state.workQuery.trim())].slice(0,6);state.searchResultIds=searchPeople().map(p=>p.id);state.peopleLimit=24;go('results',{guided:true});return true;
case 'clear-search-filters':state.searchFilters=newState().searchFilters;render();return true;
case 'open-result-world':if(state.searchResultIds.length){state.world=resultGroup();state.tab='すべて';state.worldLimit=24;go('world',{guided:true});}return true;
case 'profile-world':state.world=personWorld(state.profileId);state.tab='すべて';state.worldLimit=24;go('world');return true;
case 'follow':toggleArray('followIds',state.profileId);render(true);return true;
case 'profile-message':if(state.followIds.includes(state.profileId)||state.followerIds.includes(state.profileId)){openThread(state.profileId);}return true;
case 'new-message':go('contacts');return true;
}return false;}
function v3Input(input){if(input.dataset.profile){input.classList.toggle('is-empty',!input.value);state.profileDraft={...profileForm(),[input.dataset.profile]:input.value};const btn=$('[data-action="about-next"]')||$('[data-action="about-save"]');if(btn)btn.disabled=!validProfile();const ageInput=$('#profile-age'),ageError=$('#age-error');if(ageInput)ageInput.setAttribute('aria-invalid',String(invalidAge()));if(ageError)ageError.hidden=!invalidAge();guide();persist();return true;}if(input.id==='home-query'){state.homeQuery=input.value;state.homeLimit=24;$('#home-feed').innerHTML=pagedFeed(homeItems(),state.homeLimit,'home-more');$('#home-count').textContent=homeItems().length+'件';persist();return true;}if(input.id==='person-query'){state.personQuery=input.value;guide();persist();return true;}if(input.id==='work-query'){state.workQuery=input.value;guide();persist();return true;}if(input.dataset.searchFilter){state.searchFilters[input.dataset.searchFilter]=input.type==='checkbox'?input.checked:input.value;const error=searchValidation(),hint=$('#search-error');if(hint){hint.textContent=error;hint.hidden=!error;}const button=$('[data-action=search-run]');if(button)button.disabled=!!error;persist();return true;}if(input.id==='thread-input'){state.drafts[state.chatId]=input.value;$('.message-form button').disabled=!input.value.trim();persist();return true;}return false;}
function openProfile(id){if(!people.some(p=>p.id===id))return;state.profileId=id;go('profile');}
function openThread(id){if(!people.some(p=>p.id===id))return;if(!state.threads[id])state.threads[id]=[];state.chatId=id;go('thread');const panel=$('.app-scroll');if(panel)panel.scrollTop=panel.scrollHeight;}

